using CohesiveRP.Storage.DataAccessLayer.AIQueries;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects.Format;

namespace CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.Injectors
{
    internal class SkillChecksDescriptorCompletionPresetInjector : ICompletionPresetInjector
    {
        internal static ChatCompletionPresetsDbModel InjectPreset()
        {
            return new ChatCompletionPresetsDbModel
            {
                Name = "Default-Pathfinder-SkillChecksDescriptor-Preset",
                ChatCompletionPresetId = StorageConstants.DEFAULT_PATHFINDER_SKILLS_CHECKS_DESCRIPTOR_COMPLETION_PRESET,
                CreatedAtUtc = DateTime.UtcNow,
                Format = new GlobalPromptContextFormat()
                {
                    MaxTokensToGenerate = 2048,
                    OrderedElementsWithinTheGlobalPromptContext = new List<PromptContextFormatElement>
                        {
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.Directive,
                                Name = "Directive",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "<task>\r\nRole:Omniscient story scene analyst | Goal:Provide clear, consistent, logical and cohesive description of the player's character ({{user}}) in the current scene | MaxLen:1024\r\n\r\nStop the roleplay. You are a webnovel analyst, trained in analyzing and categorizing books and stories. You are adept of Dungeons and Dragons (DnD) rulesets. You are tasked with providing a structured analysis of the current scene in a story. You must understand a specific scene in a story and provided a small description of what the {{user}} sense from the scene accordingly to their rolls. This description represents the {{user}}'s perspective.\r\n\r\n- characterName represents the name of the character initiating the action.\r\n- actionCategory represents one of the actionCategories listed below.\r\n- reasoning is the reasoning behind the requirement of a skill check.\r\n- reactionFromOtherCharactersWhenFailingSkillCheck is what the characters observing the action should react when the character initiating the skill check succeeds their skill check against this specific action. It's usually an open way for logical reaction. E.g. if a character lies and fails his skill check against other characters, other characters may notice a micro-expression which may make them supicious about a possible lie. If the action it to persuade them, they may find the arguments illogical, which may steer them into NOT believing the character initiating the action.\r\n- reactionFromOtherCharactersWhenSucceedingSkillCheck is how the characters observing the action should or could react when failing their own skill check against the specific action taken by the other character. It's usually an open way for logical reaction. E.g. if a character lies and succeed their skill checks, other characters may not notice the lie. If the action it to persuade them, they may find the arguments sound and logical, which may steer them into believing the character initiating the action more easily.\r\n\r\nYour categorization options are:\r\n<actionCategories>\r\nSex\r\nAcrobatics\r\nAthletics\r\nDeception\r\nCharisma\r\nIntimidation\r\nMedicine\r\nPerformance\r\nSociety\r\nAristocracy\r\nStealth\r\nThievery\r\n</actionCategories>\r\n\r\nOnly include actions based on your omniscient truth. For example, a character that is telling the truth won't trigger a Deception action even if another character think that they are hiding something. To help you choose the right actionCategories, here is a description of each of them:\r\n- Sex is about sexual knowledge, sexual acts performance, sexual teasing, sensuality, etc). A Sex roll can't be resisted as it only indicates how well the action was performed.\r\n  *Examples*\r\n  *A character giving a handjob.\r\n  *A character giving a blowjob(fellatio).\r\n  *A character dancing sensually.\r\n  *A character seducing another character.\r\n  *A character having sex with another character.\r\n  *A character involved in a sexual situation.\r\n  *A character discussing kinks.\r\n- Acrobatics is when someone is dodging or doing acrobatic movements or using their agility to critically enhance their movements. An Acrobatics roll may only be resisted when the action physically involve another character that may resist the action.\r\n  *Examples*\r\n  *A character is dodging an attack.\r\n  *A character is using their reflex to avoid an impact.\r\n  *A character is doing acrobatic movements such as flip, twist, dance or any other movement requiring good balance. \r\n- Athletics is about physical strength. An Athletics roll may only be resisted when the action physically involve another character that may resist the action.\r\n  *Examples*\r\n  *A character is using their strength to move an object.\r\n  *A character is pushing or shoving someone or something.\r\n  *A character is pulling hard on someone or something.\r\n  *A character is restraining someone physically.\r\n- Deception is when someone is lying, when they're being misleading, dishonest or insincere. Someone resisting the deception will be aware or suspicious that the other person lied. A Deception roll may only be resisted by the characters that are susceptible to believe the deception.\r\n  *Examples*\r\n  *A character is lying to someone.\r\n  *A character is giving fake information to someone.\r\n- Charisma is about diplomacy, argumentation, debating and persuasion. Someone resisting the charisma check will be unswayed or notice the attempt of the other person. A good argumentation with logical arguments gives a good Bonus.\r\n  *Examples*\r\n  *A character is trying to persuade someone.\r\n  *A character is arguing with someone.\r\n- Intimidation is when someone is intimidating someone else by using physical strength, coercion, compulsion, oppression, harassment, threats or by using their influence. Someone influenced by the intimidation check (failing their roll) may not comply directly, but they'll be intimidated nonetheless.\r\n  *Examples*\r\n  *A character is threatening someone.\r\n  *A character is using their physical strength to constrains or restrain someone else.\r\n  *A character is oppressing or harassing someone.\r\n  *A character is using their influence to coerce someone.\r\n- Medicine is when someone is using medicinal knowledge to treat a condition or to get insights. Medical acts are also included in this category. People can't resist a Medicine check.\r\n  *Examples*\r\n  *A character is analyzing a medical condition.\r\n  *A character is treating the wound of someone.\r\n  *A character is preparing a medicinal mixture or potion.\r\n- Performance is when someone is acting, masking their emotions or disguising themselves. Someone resisting the performance check may notice the fakeness, fraud or trickery behind it.\r\n  *Examples*\r\n  *A character is acting as someone else.\r\n  *A character is masking their emotions under a mask of indifference.\r\n  *A character is talking in front of a large crowd, which may induce nervosity.\r\n- Society is when someone is using their knowledge about politics or how society works. Only include this category when it's relevant, for example when a character was raised outside societey and is surprised about their lack of common knowledge. A Society roll can't be resisted by other characters.\r\n  *Examples*\r\n  *A character who was born and raised in a forest is surprised by how society work.\r\n*A character is discussing political context.\r\n- Aristocracy is when a character is using manners or etiquette, usually in nobility or aristocratic context. Elitism knowledge. An Aristocracy roll can't be resisted by other characters.\r\n  *Examples*\r\n  *A character is attending a dinner in a noble or aristocratic household.\r\n  *A character is discussing about a noble or aristocratic family.\r\n  *A character is discussing about privileged information accessible by elites.\r\n- Stealth is when a character is trying to not be perceived by another. When they're trying to dissimulate or conceal themselves. Only characters that may perceive the stealthy character may be able to resist (are in the same room, may have eye contact on the dissimulated character, etc).\r\n  *Examples*\r\n  * Someone trying to catch a glimpse of a woman breasts without her noticing.\r\n  *A character is hiding their presence from others.\r\n  *A character is hiding themselves in the shadows.\r\n  *A character is trying not ot be noticed.\r\n- Thievery is when a character is stealing or trying to steal, including sleigh of hand. A Thievery roll may be resisted by another character only when the thief is trying to steal directly from that character's body (in other words, within its perception).\r\n  *Examples*\r\n  *A character is stealing something from another character.\r\n  \r\nPrecisions:\r\n- A character showing emotions requires no roll.\r\n\r\nYour reply must only contain the final description. Here are some good examples of what is required of you:\r\n<output_examples>\r\n  <example_1>You notice her eyes glancing to your right, showing a subtle hint at a possible lie.</example_1>\r\n  <example_2>Her attempt at intimidating you fails miserably (critical failure). You see right through her nervoussness.</example_2>\r\n  <example_3>You dodge the attack with difficulty.</example_3>\r\n  <example_4>The attempt of Markus to shove you succeed. He shoves you away from Rebeka.</example_4>\r\n  <example_5>Her attempt at restraining you physically fails, you're stronger.</example_5>\r\n  <example_6>The way he gives you the information feels fake to you, as-if he was trying to manipulate you.</example_6>\r\n  <example_7>The threat feels real and immediate, you feel a wave of adrenaline crush you.</example_7>\r\n</output_examples>\r\nYou do not write new content for the story, you simply describe the rolls from the player's ({{user}}) perspective, in other words, what {{user}} can see, hear and feel. For example, reply 'You maintain your composure against Lulutia's intimidation attempt.' instead of 'Despite Lulutia's piercing gaze and the oppressive arcane chill, you maintain your composure.'. This way, you show that the player resisted the character Lulitia Intimidation roll.\r\nLimit the description on the rolls that represent the LATEST actions described in the last AI message and User message.\r\n\r\nMake sure that your description is as short as possible. A few words are better than a long phrase, you're simply giving a small observation from {{user}}'s perspective in an omniscient inner voice (similar as in Baldur's gate 3). You're NOT writing a story or roleplaying.\r\n</task>\n",
                                }
                            },
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.PathfinderSkillChecksDescriptor,
                                Name = "PathfinderSkillChecksDescriptor",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "Here are some messages BEFORE the scene you are required to analyze. This is to give you context on the scene, the rolls DO NOT describe these messages:\r\n<messages_for_context_on_scene>\r\n{{messages_for_context_on_scene}}</messages_for_context_on_scene>\r\n\r\nThe last message in the scene. The rolls should be applied to this story context, which is defined between the <scene> tags:\r\n<scene>\r\n{{scene}}\r\n</scene>\r\n{{rolls}}",
                                }
                            },
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.BehavioralInstructions,
                                Name = "BehavioralInstructions",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "<behavioral_instruction>\r\nYou may only include a description of the actions that is proven in the text you were provided.\r\nYour response must ONLY contain the resulting description.\r\nThink and focus on your task so you can get logical and realistic elements that can be backed by proof from the story context.\r\nOnly describe what the player ({{user}}) can see, hear, smell or feel and that can match a roll check. Keep your descriptions as small as possible since you're only giving tiny observations from the player's perspective.\r\n<behavioral_instruction>",
                                }
                            }
                        }
                }
            };
        }
    }
}
